-- Default REQUEST SLA policies: workflow_type x priority matrix.
-- Until now no applies_to='REQUEST' policy existed, so no Service Request
-- ever got an SlaInstance. Targets are business minutes against the shared
-- Standard Business Hours calendar (...0030) seeded in V39.
--
-- Matching: exact workflow_type wins over a NULL (generic) filter; these are
-- all workflow-specific so every catalog item resolves to its own policy.
--
--   INSTANT  (Password Reset / Account Unlock):       15m-1h response, 1-8h resolution
--   SOFTWARE (Clinical Software, Email, Access, ...): 30m-4h response, 4-48h resolution
--   FULL     (Workstation, Printer, Mobile, Network): 1-8h response,   24-240h resolution
INSERT INTO sla_policy (id, org_id, name, applies_to, priority_filter, workflow_type,
                        response_target_minutes, resolution_target_minutes,
                        business_hours_calendar_id, created_by, updated_by)
VALUES
    -- INSTANT
    ('00000000-0000-0000-0000-000000000060'::uuid, '00000000-0000-0000-0000-000000000001'::uuid, 'SR SLA - Instant / Critical', 'REQUEST', 'Critical', 'INSTANT', 15,  60,   '00000000-0000-0000-0000-000000000030'::uuid, '00000000-0000-0000-0000-000000000000'::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
